// Thin Lago REST client (Node 18+, no dependencies). Server-side only: never import from client components.
import { createHmac, createPublicKey, timingSafeEqual, verify as verifySignature } from "node:crypto";

export type LagoConfig = {
  apiUrl: string; // origin only, e.g. https://api.getlago.com (US) or https://api.eu.getlago.com (EU); "/api/v1" is appended here
  apiKey: string;
  timeoutMs?: number;
  maxAttempts?: number;
  fetchImpl?: typeof fetch;
  sleep?: (ms: number) => Promise<void>;
};

export class LagoError extends Error {
  constructor(message: string, readonly status: number | null, readonly body: unknown, readonly retryable: boolean) {
    super(message);
  }
}

export function configFromEnv(env: Record<string, string | undefined> = process.env): LagoConfig {
  const apiUrl = env.LAGO_API_URL?.trim();
  const apiKey = env.LAGO_API_KEY?.trim();
  if (!apiUrl) throw new Error("LAGO_API_URL is not set (choose your Lago region or self-hosted origin explicitly)");
  if (!apiKey) throw new Error("LAGO_API_KEY is not set");
  return { apiUrl: apiUrl.replace(/\/+$/, "").replace(/\/api\/v1$/, ""), apiKey };
}

const defaultSleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));
const isRetryableStatus = (status: number) => status === 429 || status >= 500;

async function request<T>(config: LagoConfig, method: string, path: string, body?: unknown): Promise<T> {
  const fetchImpl = config.fetchImpl ?? fetch;
  const sleep = config.sleep ?? defaultSleep;
  const maxAttempts = config.maxAttempts ?? 4;
  const payload = body === undefined ? undefined : JSON.stringify(body); // serialized once: retries send identical bytes

  for (let attempt = 1; ; attempt++) {
    let error: LagoError;
    try {
      const response = await fetchImpl(`${config.apiUrl}/api/v1${path}`, {
        method,
        headers: { Authorization: `Bearer ${config.apiKey}`, "Content-Type": "application/json", Accept: "application/json" },
        body: payload,
        signal: AbortSignal.timeout(config.timeoutMs ?? 10_000),
      });
      const text = await response.text();
      const parsed = text ? safeJson(text) : null;
      if (response.ok) return parsed as T;
      error = new LagoError(`Lago ${method} ${path} failed with ${response.status}`, response.status, parsed, isRetryableStatus(response.status));
    } catch (cause) {
      // Network failure or timeout: the request may or may not have reached Lago, so it is safe to retry
      // only because every write we send carries a stable identifier.
      error = new LagoError(`Lago ${method} ${path} network error: ${(cause as Error).message}`, null, null, true);
    }
    if (!error.retryable || attempt >= maxAttempts) throw error;
    const backoff = Math.min(8_000, 250 * 2 ** (attempt - 1));
    await sleep(backoff / 2 + Math.random() * (backoff / 2));
  }
}

function safeJson(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

// ---- Customers and subscriptions ----

export type CustomerInput = { externalId: string; name: string; email?: string; currency?: string };

export function upsertCustomer(config: LagoConfig, customer: CustomerInput) {
  // POST /customers creates or updates by external_id.
  return request<{ customer: Record<string, unknown> }>(config, "POST", "/customers", {
    customer: { external_id: customer.externalId, name: customer.name, email: customer.email, currency: customer.currency },
  });
}

export type SubscriptionInput = { externalId: string; externalCustomerId: string; planCode: string };

export function createSubscription(config: LagoConfig, subscription: SubscriptionInput) {
  return request<{ subscription: Record<string, unknown> }>(config, "POST", "/subscriptions", {
    subscription: {
      external_id: subscription.externalId,
      external_customer_id: subscription.externalCustomerId,
      plan_code: subscription.planCode,
    },
  });
}

// ---- Usage events ----

export type UsageEvent = {
  transactionId: string; // derived from a durable source record, never random per attempt
  externalSubscriptionId: string;
  code: string;
  timestamp: number; // Unix seconds of the original occurrence; must not change across retries
  properties: Record<string, string | number>;
};

export function validateUsageEvent(event: UsageEvent, numericProperties: string[] = ["tokens"]) {
  const problems: string[] = [];
  if (!event.transactionId) problems.push("transactionId is required");
  if (!event.externalSubscriptionId) problems.push("externalSubscriptionId is required");
  if (!event.code) problems.push("code is required");
  if (!Number.isInteger(event.timestamp) || event.timestamp < 0) problems.push("timestamp must be non-negative integer Unix seconds");
  for (const key of numericProperties) {
    const value = event.properties[key];
    if (typeof value !== "number" || !Number.isFinite(value) || value < 0) problems.push(`properties.${key} must be a finite non-negative number`);
  }
  if (problems.length) throw new Error(`Invalid usage event: ${problems.join("; ")}`);
}

export type SendUsageResult = { status: "accepted" } | { status: "duplicate" };

function isDuplicateTransaction(error: LagoError) {
  const body = error.body as { error_details?: { transaction_id?: unknown } } | null;
  const details = body?.error_details?.transaction_id;
  return error.status === 422 && Array.isArray(details) && details.includes("value_already_exist");
}

/**
 * Sends one usage event. "duplicate" means Lago already holds an event with this transaction_id;
 * it is NOT proof of delivery — the caller must reconcile it with findStoredEvent before marking it delivered.
 */
export async function sendUsage(config: LagoConfig, event: UsageEvent): Promise<SendUsageResult> {
  validateUsageEvent(event);
  try {
    await request(config, "POST", "/events", {
      event: {
        transaction_id: event.transactionId,
        external_subscription_id: event.externalSubscriptionId,
        code: event.code,
        timestamp: event.timestamp,
        properties: event.properties,
      },
    });
    return { status: "accepted" };
  } catch (error) {
    if (error instanceof LagoError && isDuplicateTransaction(error)) return { status: "duplicate" };
    throw error;
  }
}

type StoredEvent = {
  transaction_id: string;
  external_subscription_id: string;
  code: string;
  timestamp: string;
  properties: Record<string, unknown>;
};

/** Looks up the stored event scoped to subscription, metric and exact timestamp (paginated). */
export async function findStoredEvent(config: LagoConfig, event: UsageEvent): Promise<StoredEvent | null> {
  const at = new Date(event.timestamp * 1000).toISOString();
  for (let page = 1; page <= 50; page++) {
    const query = new URLSearchParams({
      external_subscription_id: event.externalSubscriptionId,
      code: event.code,
      timestamp_from: at,
      timestamp_to: at,
      page: String(page),
      per_page: "100",
    });
    const result = await request<{ events: StoredEvent[]; meta?: { next_page?: number | null } }>(config, "GET", `/events?${query}`);
    const match = result.events.find((stored) => stored.transaction_id === event.transactionId);
    if (match) return match;
    if (!result.meta?.next_page) return null;
  }
  return null;
}

/** True only when the stored event is the same source record (subscription, metric, time and properties). */
export function matchesStoredEvent(event: UsageEvent, stored: StoredEvent): boolean {
  if (stored.external_subscription_id !== event.externalSubscriptionId || stored.code !== event.code) return false;
  if (Math.floor(Date.parse(stored.timestamp) / 1000) !== event.timestamp) return false;
  return Object.entries(event.properties).every(([key, value]) => String(stored.properties?.[key]) === String(value));
}

// ---- Reads ----

export function currentUsage(config: LagoConfig, externalCustomerId: string, externalSubscriptionId: string) {
  const query = new URLSearchParams({ external_subscription_id: externalSubscriptionId });
  return request<{ customer_usage: Record<string, unknown> }>(
    config,
    "GET",
    `/customers/${encodeURIComponent(externalCustomerId)}/current_usage?${query}`,
  );
}

export async function webhookPublicKey(config: LagoConfig): Promise<string> {
  // Lago returns the RSA public key base64-encoded; decode to PEM.
  const encoded = await request<string>(config, "GET", "/webhooks/public_key");
  return Buffer.from(String(encoded).trim(), "base64").toString("utf8");
}

// ---- Webhooks ----

export type WebhookVerification =
  | { algorithm: "jwt"; publicKeyPem: string; issuer: string }
  | { algorithm: "hmac"; hmacKey: string };

/** Verifies a Lago webhook against the exact raw body bytes received. Never pass a re-serialized body. */
export function verifyWebhook(rawBody: string, headers: Headers, verification: WebhookVerification): boolean {
  const signature = headers.get("x-lago-signature");
  const algorithm = headers.get("x-lago-signature-algorithm");
  if (!signature || algorithm !== verification.algorithm) return false;

  if (verification.algorithm === "hmac") {
    const expected = createHmac("sha256", verification.hmacKey).update(rawBody, "utf8").digest();
    const received = Buffer.from(signature, "base64");
    return received.length === expected.length && timingSafeEqual(received, expected);
  }

  // RS256 JWT whose `data` claim is the raw body and `iss` is the Lago API URL.
  const parts = signature.split(".");
  if (parts.length !== 3) return false;
  const [encodedHeader, encodedPayload, encodedSignature] = parts;
  try {
    const header = JSON.parse(Buffer.from(encodedHeader, "base64url").toString("utf8"));
    if (header.alg !== "RS256") return false;
    const signed = verifySignature(
      "RSA-SHA256",
      Buffer.from(`${encodedHeader}.${encodedPayload}`),
      createPublicKey(verification.publicKeyPem),
      Buffer.from(encodedSignature, "base64url"),
    );
    if (!signed) return false;
    const claims = JSON.parse(Buffer.from(encodedPayload, "base64url").toString("utf8"));
    return claims.iss === verification.issuer && claims.data === rawBody;
  } catch {
    return false;
  }
}

// Stand-in for the app's database.
export type Workspace = { id: string; name: string; email: string; plan: "free" | "pro" };
export type Generation = { id: string; workspaceId: string; model: string; inputTokens: number; outputTokens: number; createdAt: Date };
// Links a workspace (Lago customer) to its Lago subscription. Kept separate from the customer identity.
export type BillingEnrollment = {
  workspaceId: string;
  externalCustomerId: string;
  externalSubscriptionId: string;
  planCode: string;
  status: "pending" | "active";
  activatedAt: Date | null;
};
// Delivery status lives apart from the source Generation so usage can be replayed and reconciled.
export type UsageDelivery = {
  generationId: string;
  transactionId: string;
  status: "pending" | "delivered" | "failed" | "needs_investigation" | "not_billable";
  attempts: number;
  lastError: string | null;
  updatedAt: Date;
};
export type WebhookEnvelope = { uniqueKey: string; type: string | null; rawBody: string; receivedAt: Date; processedAt: Date | null };
export const db = {
  workspaces: new Map<string, Workspace>(),
  generations: new Map<string, Generation>(),
  billingEnrollments: new Map<string, BillingEnrollment>(), // keyed by workspaceId
  usageDeliveries: new Map<string, UsageDelivery>(), // keyed by generationId
  webhookEvents: new Map<string, WebhookEnvelope>(), // keyed by X-Lago-Unique-Key (unique constraint)
};

import type { BillingEnrollment, Generation } from "@/lib/db";
import type { UsageEvent } from "./lago";

export const TOKENS_METRIC_CODE = "llm_tokens";

/** One Generation → one usage event. The transaction ID and timestamp come from the stored record, so retries are identical. */
export function generationToUsageEvent(generation: Generation, enrollment: BillingEnrollment): UsageEvent {
  return {
    transactionId: `gen_${generation.id}`,
    externalSubscriptionId: enrollment.externalSubscriptionId,
    code: TOKENS_METRIC_CODE,
    timestamp: Math.floor(generation.createdAt.getTime() / 1000),
    properties: { tokens: generation.inputTokens + generation.outputTokens, model: generation.model },
  };
}

// Billing adapter: the only place app code talks to Lago. Lago owns rating, credits and invoices;
// this module owns identity mapping and reliable delivery of usage source records.
import { db, type UsageDelivery } from "@/lib/db";
import { generationToUsageEvent } from "./events";
import { configFromEnv, createSubscription, findStoredEvent, LagoError, matchesStoredEvent, sendUsage, upsertCustomer } from "./lago";

export const PRO_PLAN_CODE = process.env.LAGO_PLAN_CODE ?? "pro";

/** Creates the Lago customer and subscription for a workspace. Safe to call again: identifiers are stable. */
export async function enrollWorkspace(workspaceId: string) {
  const workspace = db.workspaces.get(workspaceId);
  if (!workspace) throw new Error(`Unknown workspace ${workspaceId}`);
  const config = configFromEnv();

  let enrollment = db.billingEnrollments.get(workspaceId);
  if (enrollment?.status === "active") return enrollment;
  if (!enrollment) {
    enrollment = {
      workspaceId,
      externalCustomerId: workspace.id,
      externalSubscriptionId: `sub_${crypto.randomUUID()}`, // persisted before the Lago call, reused on retry
      planCode: PRO_PLAN_CODE,
      status: "pending",
      activatedAt: null,
    };
    db.billingEnrollments.set(workspaceId, enrollment);
  }

  await upsertCustomer(config, { externalId: enrollment.externalCustomerId, name: workspace.name, email: workspace.email });
  try {
    await createSubscription(config, {
      externalId: enrollment.externalSubscriptionId,
      externalCustomerId: enrollment.externalCustomerId,
      planCode: enrollment.planCode,
    });
  } catch (error) {
    // A retry after a lost response may hit an already-created subscription; anything else is a real failure.
    if (!(error instanceof LagoError && error.status === 422 && JSON.stringify(error.body).includes("value_already_exist"))) throw error;
  }
  enrollment.status = "active";
  enrollment.activatedAt = new Date();
  return enrollment;
}

/** Delivers the usage for one stored Generation. Never throws: failures are recorded for replay. */
export async function deliverGenerationUsage(generationId: string): Promise<UsageDelivery> {
  const generation = db.generations.get(generationId);
  if (!generation) throw new Error(`Unknown generation ${generationId}`);
  const transactionId = `gen_${generation.id}`;
  const delivery: UsageDelivery = db.usageDeliveries.get(generationId) ?? {
    generationId,
    transactionId,
    status: "pending",
    attempts: 0,
    lastError: null,
    updatedAt: new Date(),
  };
  db.usageDeliveries.set(generationId, delivery);
  if (delivery.status === "delivered" || delivery.status === "not_billable") return delivery;

  const enrollment = db.billingEnrollments.get(generation.workspaceId);
  // Usage before the subscription starts would be stored by Lago but never billed, so it is not sent.
  if (!enrollment || enrollment.status !== "active" || !enrollment.activatedAt || generation.createdAt < enrollment.activatedAt) {
    return update(delivery, "not_billable", null);
  }

  const event = generationToUsageEvent(generation, enrollment);
  delivery.attempts += 1;
  try {
    const config = configFromEnv();
    const result = await sendUsage(config, event);
    if (result.status === "accepted") return update(delivery, "delivered", null);

    // Duplicate transaction_id: delivered only if Lago holds this exact record.
    const stored = await findStoredEvent(config, event);
    if (stored && matchesStoredEvent(event, stored)) return update(delivery, "delivered", null);
    return update(delivery, "needs_investigation", "transaction_id already exists in Lago with different or unmatched data");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(JSON.stringify({ msg: "lago_usage_delivery_failed", generationId, transactionId, error: message }));
    return update(delivery, "failed", message);
  }
}

/** Re-sends pending/failed usage with the original transaction IDs and timestamps. Run from a job or cron. */
export async function replayUndeliveredUsage() {
  const results: UsageDelivery[] = [];
  for (const generationId of db.generations.keys()) {
    const delivery = db.usageDeliveries.get(generationId);
    if (!delivery || delivery.status === "pending" || delivery.status === "failed") results.push(await deliverGenerationUsage(generationId));
  }
  return results;
}

function update(delivery: UsageDelivery, status: UsageDelivery["status"], lastError: string | null) {
  delivery.status = status;
  delivery.lastError = lastError;
  delivery.updatedAt = new Date();
  return delivery;
}

import { after } from "next/server";
import { db } from "@/lib/db";
import { summarize } from "@/lib/llm";
import { deliverGenerationUsage } from "@/lib/billing/service";

export async function POST(request: Request) {
  const { workspaceId, text } = await request.json();
  const result = await summarize(text);
  const generation = {
    id: crypto.randomUUID(),
    workspaceId,
    model: result.model,
    inputTokens: result.usage.input_tokens,
    outputTokens: result.usage.output_tokens,
    createdAt: new Date(),
  };
  // The stored generation is the durable usage source record; billing reads from it, never from the request.
  db.generations.set(generation.id, generation);
  after(() => deliverGenerationUsage(generation.id));
  return Response.json({ summary: result.summary });
}

import { after } from "next/server";
import { db } from "@/lib/db";
import { configFromEnv, verifyWebhook, webhookPublicKey, type WebhookVerification } from "@/lib/billing/lago";

let cachedPublicKey: string | null = null;

async function verification(): Promise<WebhookVerification> {
  const hmacKey = process.env.LAGO_WEBHOOK_HMAC_KEY;
  if (hmacKey) return { algorithm: "hmac", hmacKey };
  const config = configFromEnv();
  cachedPublicKey ??= await webhookPublicKey(config);
  return { algorithm: "jwt", publicKeyPem: cachedPublicKey, issuer: config.apiUrl };
}

export async function POST(request: Request) {
  const rawBody = await request.text(); // verify the exact bytes Lago signed, before any JSON parsing
  if (!verifyWebhook(rawBody, request.headers, await verification())) return new Response(null, { status: 401 });

  const uniqueKey = request.headers.get("x-lago-unique-key");
  if (!uniqueKey) return new Response(null, { status: 400 });
  if (!db.webhookEvents.has(uniqueKey)) {
    let type: string | null = null;
    try {
      type = JSON.parse(rawBody).webhook_type ?? null;
    } catch {
      return new Response(null, { status: 400 });
    }
    db.webhookEvents.set(uniqueKey, { uniqueKey, type, rawBody, receivedAt: new Date(), processedAt: null });
    after(() => processWebhook(uniqueKey));
  }
  // Acknowledge only after the envelope is durably stored; duplicates are acknowledged without reprocessing.
  return new Response(null, { status: 204 });
}

async function processWebhook(uniqueKey: string) {
  const envelope = db.webhookEvents.get(uniqueKey);
  if (!envelope || envelope.processedAt) return;
  console.info(JSON.stringify({ msg: "lago_webhook_received", uniqueKey, type: envelope.type }));
  // Handle the types you care about here (e.g. invoice.created, invoice.payment_status_updated). Handlers must be idempotent.
  envelope.processedAt = new Date();
}

