// One-time Lago catalog setup. Writes to the Lago organization behind LAGO_API_KEY, so it requires --apply.
// Usage: LAGO_API_URL=... LAGO_API_KEY=... node scripts/lago-setup.ts --apply
import { configFromEnv, createBillableMetric, createPlan } from "../lib/billing/lago.ts";

// Example pricing — replace with your real prices before running.
const metric = { code: "llm_tokens", name: "LLM tokens", fieldName: "tokens" };
const plan = {
  code: process.env.LAGO_PLAN_CODE ?? "pro",
  name: "Pro",
  amountCents: 4900, // $49.00 / month, billed in advance
  currency: "USD",
  meteredChargeMetricCode: metric.code,
  perUnitAmount: "0.00002", // $0.02 per 1,000 tokens
};

const config = configFromEnv();
if (!process.argv.includes("--apply")) {
  console.log(`Dry run against ${config.apiUrl}. Would create:`, JSON.stringify({ metric, plan }, null, 2));
  console.log("Re-run with --apply to create them.");
} else {
  await createBillableMetric(config, metric);
  await createPlan(config, plan);
  console.log(`Created billable metric "${metric.code}" and plan "${plan.code}" on ${config.apiUrl}.`);
}

// Offline tests: node --test lib/billing/   (Node 22.6+ strips TypeScript types natively)
import { test } from "node:test";
import assert from "node:assert/strict";
import { createHmac, createSign, generateKeyPairSync } from "node:crypto";
import { configFromEnv, matchesStoredEvent, sendUsage, verifyWebhook, type LagoConfig, type UsageEvent } from "./lago.ts";
import { generationToUsageEvent } from "./events.ts";

type Call = { url: string; init: RequestInit };

function fakeLago(responses: Array<Response | Error>) {
  const calls: Call[] = [];
  const fetchImpl = (async (url: string, init: RequestInit) => {
    calls.push({ url, init });
    const next = responses.shift();
    if (!next) throw new Error("unexpected call");
    if (next instanceof Error) throw next;
    return next;
  }) as unknown as typeof fetch;
  const config: LagoConfig = { apiUrl: "https://lago.test", apiKey: "test-key", fetchImpl, sleep: async () => {} };
  return { config, calls };
}

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status });
const duplicateBody = { status: 422, error: "Unprocessable Entity", code: "validation_errors", error_details: { transaction_id: ["value_already_exist"] } };

const event: UsageEvent = {
  transactionId: "gen_123",
  externalSubscriptionId: "sub_abc",
  code: "llm_tokens",
  timestamp: 1_760_000_000,
  properties: { tokens: 1200, model: "gpt-4.1-mini" },
};

test("configFromEnv requires an explicit API URL and normalizes /api/v1", () => {
  assert.throws(() => configFromEnv({ LAGO_API_KEY: "k" }), /LAGO_API_URL/);
  assert.equal(configFromEnv({ LAGO_API_URL: "https://api.getlago.com/api/v1/", LAGO_API_KEY: "k" }).apiUrl, "https://api.getlago.com");
});

test("transient failures are retried with the identical transaction_id and timestamp", async () => {
  const { config, calls } = fakeLago([new TypeError("fetch failed"), json(503, {}), json(429, {}), json(200, { event: {} })]);
  assert.deepEqual(await sendUsage(config, event), { status: "accepted" });
  assert.equal(calls.length, 4);
  const bodies = calls.map((call) => call.init.body);
  assert.ok(bodies.every((body) => body === bodies[0]));
  const sent = JSON.parse(String(bodies[0])).event;
  assert.equal(sent.transaction_id, "gen_123");
  assert.equal(sent.timestamp, 1_760_000_000);
  assert.equal(sent.external_subscription_id, "sub_abc");
  assert.equal(calls[0].url, "https://lago.test/api/v1/events");
});

