test("HMAC webhooks: valid signature accepted, tampered body rejected", () => {
  const body = '{"webhook_type":"invoice.created","invoice":{"total_amount_cents":5140}}';
  const signature = createHmac("sha256", "hmac-secret").update(body).digest("base64");
  const headers = new Headers({ "x-lago-signature": signature, "x-lago-signature-algorithm": "hmac" });
  assert.equal(verifyWebhook(body, headers, { algorithm: "hmac", hmacKey: "hmac-secret" }), true);
  assert.equal(verifyWebhook(body.replace("5140", "1"), headers, { algorithm: "hmac", hmacKey: "hmac-secret" }), false);
  assert.equal(verifyWebhook(body, headers, { algorithm: "hmac", hmacKey: "wrong" }), false);
});

test("JWT webhooks: valid signature accepted, tampered body or issuer rejected", () => {
  const { publicKey, privateKey } = generateKeyPairSync("rsa", { modulusLength: 2048 });
  const publicKeyPem = publicKey.export({ type: "spki", format: "pem" }).toString();
  const body = '{"webhook_type":"invoice.created"}';
  const b64 = (value: unknown) => Buffer.from(JSON.stringify(value)).toString("base64url");
  const signingInput = `${b64({ alg: "RS256", typ: "JWT" })}.${b64({ data: body, iss: "https://lago.test" })}`;
  const jwt = `${signingInput}.${createSign("RSA-SHA256").update(signingInput).sign(privateKey).toString("base64url")}`;
  const headers = new Headers({ "x-lago-signature": jwt, "x-lago-signature-algorithm": "jwt" });
  const verification = { algorithm: "jwt" as const, publicKeyPem, issuer: "https://lago.test" };
  assert.equal(verifyWebhook(body, headers, verification), true);
  assert.equal(verifyWebhook('{"webhook_type":"tampered"}', headers, verification), false);
  assert.equal(verifyWebhook(body, headers, { ...verification, issuer: "https://evil.test" }), false);
});

test("money: 120,000 tokens at $0.00002 is $2.40 on top of the $49.00 plan fee", () => {
  const enrollment = {
    workspaceId: "ws_1",
    externalCustomerId: "ws_1",
    externalSubscriptionId: "sub_1",
    planCode: "pro",
    status: "active" as const,
    activatedAt: new Date("2026-10-01T00:00:00Z"),
  };
  const generations = [
    { inputTokens: 50_000, outputTokens: 10_000 },
    { inputTokens: 45_000, outputTokens: 15_000 },
  ].map((tokens, i) => ({ id: `g${i}`, workspaceId: "ws_1", model: "gpt-4.1-mini", createdAt: new Date("2026-10-02T00:00:00Z"), ...tokens }));
  const events = generations.map((generation) => generationToUsageEvent(generation, enrollment));
  assert.deepEqual(events.map((e) => e.transactionId), ["gen_g0", "gen_g1"]);

  const totalTokens = events.reduce((sum, e) => sum + Number(e.properties.tokens), 0);
  assert.equal(totalTokens, 120_000);
  // Integer arithmetic: $0.00002/token = 2 cents per 1,000 tokens.
  const usageCents = (totalTokens * 2) / 1000;
  assert.equal(usageCents, 240);
  assert.equal(4900 + usageCents, 5140);
});

